"""# 📊 Serialization and Deserialization in Python

## 🔹 What is Serialization?
Serialization is the process of converting Python data types into JSON format.

## 🔹 What is Deserialization?
Deserialization is the process of converting JSON data back into Python data types.



![demo-interactive.gif](data:image/gif;base64,)
"""

# Serilization usinng json module
#list
import json

l = [1,2,3,4]

with open('demo.json','w') as f:
  json.dump(l,f)

# dict
d = {
    'name':'ravi',
    'age':33,
    'gender':'male'
}

with open('demo.json','w' ) as f:
  json.dump(d,f,indent=4)

import json

with open ('demo.json','r') as f:
  data = json.load(f)
  print(data)
  print(type(data))

