"""## Serializng and Deserializing custom objects"""

class Person:

  def __init__(self,fname,lname,age ,gendar):
    self.fname = fname
    self.lname = lname
    self.age = age
    self.gendar= gendar

 # format to printed in
 # -. Nitish Singh age -> 33 gendar -> male

person =Person('Nitish','Singh',33,'male')

# as a string
import json

def show_object(person):
  if isinstance(person,Person):
    return "{} {} age -> {} gendar -> {} ".format(person.fname,person.lname,person.age,person.gendar)

with open('demo.json','w') as f:
  json.dump(person,f,default=show_object)

#As a dist
# as a string
import json

def show_object(person):
  if isinstance(person,Person):
    return {'name':person.fname + ' ' + person.lname,'age':person.age,'gendar':person.gendar }

with open('demo.json','w') as f:
  json.dump(person,f,default=show_object,indent =4)

# indent atribuute
# as a dict

# deserialzation
import json

with open ('demo.json','r') as f:
  print(json.load(f))

